package minimercado.modelo;
/** Línea de una factura. Valida que no se vendan más unidades de las disponibles. */
public class DetalleFactura { private int idDetalleFactura,cantidad; private Producto producto; private double precioUnitario,descuento,subtotal; public DetalleFactura(int id,Producto p,int c,double precio,double descuento){if(c<=0||c>p.getStock())throw new IllegalArgumentException("Stock insuficiente.");if(precio<0||descuento<0)throw new IllegalArgumentException("Valores inválidos.");idDetalleFactura=id;producto=p;cantidad=c;precioUnitario=precio;this.descuento=descuento;calcularSubtotal();} public double calcularSubtotal(){return subtotal=(cantidad*precioUnitario)-descuento;} public Producto getProducto(){return producto;} public int getCantidad(){return cantidad;} public double getSubtotal(){return subtotal;} }
